add_action( 'wp_enqueue_scripts', 'perfectpixel_remove_block_library_css', 100 );

function perfectpixel_remove_block_library_css() {
	if ( function_exists( 'wp_is_block_theme' ) && wp_is_block_theme() ) {
		return;
	}
	$handles = array( 'wp-block-library', 'wp-block-library-theme', 'classic-theme-styles' );
	if ( 'no' === strtolower( trim( '{{block_css_keep_woocommerce}}' ) ) ) {
		$handles[] = 'wc-blocks-style';
	}
	foreach ( $handles as $handle ) {
		wp_dequeue_style( $handle );
	}
}
